In this paper, we consider the following decentralized optimization problem over an undirected and connected network containing $n$ nodes
\begin{equation}\label{obj_fun1}
	\mathop {\min } \limits_{\m{z} \in {\R^p}} \; F(\m{z}):= \frac{1}{n}\sum\limits_{i = 1}^n {{f_i}(\m{z})},
\end{equation}

In addition,  we define $\overline{\nabla} f(\m{x}^t)=\frac{1}{n} \sum_{i=1}^n \nabla f_i(\m{x}_i^t) 
\in \R^p$.
We say that $\m{x}$ is consensual or gets consensus if ${\m{x}_1}={\m{x}_2}=\ldots={\m{x}_n}$. 
$\m{I}_p$ denotes the $p \times p$ identity matrix and $\m{I}$ denote $\m{I}_{np}$ for simplicity. Kronecker Product is denoted as $\otimes$.
Given a vector $\m{v}$ and a matrix $\m{N}$, $\operatorname{span}(\m{v})$ stands for the linear subspace spanned by $\m{v}$;  $\left\|\m{v}\right\|_{\m{N}}^2$ denotes $\m{v}\tr \m{N} \m{v}$;
$\mbox{Null}(\m{N})$ and $\m{N}\tr$  denote the null space and transpose of $\m{N}$, respectively;
${\lambda _{\min }(\m{N})}$,  ${\lambda _{\max }(\m{N})}$, and $\rho(\m{N})$ denote smallest eigenvalue, largest eigenvalue, and  the spectral radius of $\m{N}$,  respectively;
For matrices $\m{N}_1$ and $\m{N}_2$ with same dimension, $\m{N}_1 \succeq \m{N}_2$ means $\m{N}_1 - \m{N}_2$ is positive semidefinite, while $\m{N}_1 \ge \m{N}_2$ means $\m{N}_1 - \m{N}_2$ is component-wise nonnegative.
We denote $\operatorname{log}_{10}(\cdot)$ by $\operatorname{log}(\cdot)$  and define $\m{M}=\frac{1}{n} \m{1}_n\m{1}_n\tr\otimes \m{I}_p$ where $\m{1}_n \in \R^n$ denotes the
vector with all components ones.

\begin{assum}\label{as0}
The local objective functions $\{f_i \}_{i=1}^n$ are bounded below and Lipschitz continuously differentiable, that is, for any $\m{z}, \tilde{\m{z}} \in \R^p$ and $i=1, \ldots,n$, 
we have  $f_i(z)>-\infty$ and 
	\begin{equation}\label{3.1}
		\left\| {\nabla {f_i}(\m{z}) - \nabla {f_i}(\tilde{\m{z}})} \right\| \le L \left\| {\m{z} - \tilde{\m{z}}} \right\|,
	\end{equation}
\end{assum}

\begin{defin}\label{mix}
	(Mixing matrix $\tilde{\m{W}}$ for given network $\mathcal{G} = \left(\mathcal{V},\mathcal{E}\right)$)
	\begin{itemize}
		\item [1.] $\tilde{\m{W}}$ is nonnegative, where each component $\tilde{W}_{ij}$ characterizes the active link $(i,j)$, i.e., $\tilde{{W}}_{i,j}>0$ if $j \in \mathcal{N}_i$;  $\tilde{{W}}_{i,j}=0$, otherwise.
		\item [2.] $\tilde{\m{W}}$ is symmetric and doubly stochastic, i.e., $\tilde{\m{W}}=\tilde{\m{W}}\tr$ and $\tilde{\m{W}}\m{1}_n=\m{1}_n$.\\
	\end{itemize}
\end{defin}

\begin{lemma}\label{property W}
For $\tilde{\m{W}}$ defined in Definition~\ref{mix} and  $\m{W} :=\tilde{\m{W}}\otimes\m{I}_p$, we have
	\begin{itemize}
		\item [1.] $1=\lambda_{1}(\tilde{\m{W}})>\lambda_{2}(\tilde{\m{W}})\geq\ldots\geq\lambda_{n}(\tilde{\m{W}})>-1$;
		\item [2.] $	0<\rho(\m{W}-\m{M})=\sigma=\max \left\{|\lambda_{2}(\tilde{\m{W}})|, |\lambda_{n}(\tilde{\m{W}})|\right\}<1$;
		\item [3.] $\m{M}=\m{M}\m{W}=\m{W}\m{M}$;
		\item [4.]  $\|\m{W}\m{x}-\m{M}\m{x}\|=\|(\m{W}-\m{M})(\m{x}-\m{M}\m{x})\| \leq \sigma \|\m{x}-\m{M}\m{x}\|$
		for any $\m{x} \in \R^{np}$. 
	\end{itemize}
\end{lemma}

\begin{lemma}\label{important}
	(Jensen's inequality) For any set of vectors $\{\m{v}_i\}_{i=1}^n \subset \R^p$, we have
	$$\left\|\frac{1}{n}\sum_{i=1}^n\m{v}_i\right\|^2\leq\frac{1}{n}\sum_{i=1}^n\left\|\m{v}_i\right\|^2.$$ 
\end{lemma}

\begin{lemma}\label{lem2.5a}
	 Assume $\alpha$ is some constant in $(0,\frac{1}{4L}]$. Define the sequence $\left\{\xi^t\right\}$ as
 \begin{equation}\label{def-xi}
	\xi^0=1 ; \quad \xi^{t+1}=1+L \alpha (\xi^t)^2, \quad t \geq 0 .
 \end{equation}
	Then, we have $ 1 \leq \xi^t<c $ for all $ t \geq 0$,
	where $ c \in (0,2] $ is a constant given as
\begin{equation}\label{const-c}
	c=2\left(1+\sqrt{1-4L \alpha}\right)^{-1}.
\end{equation}
\end{lemma}

Specifically, we introduce a variable $\m{v}_i$ on node $i$ to track the local gradient average by a dynamical average consensus technique \cite{sayed2014diffusion}.
Initializing  $\m{v}_i^0=\m{g}_i^0$, we use the ATC structure to update  $\m{v}_i^{t+1}$ as
\begin{equation}\label{tracking}
		\m{v}_i^{t+1}=\sum_{j \in \mathcal{N}_i}\tilde{W}_{ij}(\m{v}_j^{t}+\m{g}_j^{t+1}-\m{g}_j^{t}).
\end{equation}

where
\begin{equation*}
	{\bm{\beta}^{t+1}} = \left[ {\begin{array}{*{20}{c}}
			{{ \beta_1^{t+1}}\m{I}_p
			}&{}&{}\\
			{}&\ddots&{}\\
			{}&{}&{\beta_n^{t+1}}\m{I}_p
	\end{array}} \right] \in \R^{np \times np}.
\end{equation*}

\begin{equation}\label{Potential-P}
	P(\m{x}^{t},\m{v}^{t})=F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}+\|\m{x}^{t}-\m{M}\m{x}^{t}\|^2+\|\m{v}^{t}-\m{M}\m{v}^{t}\|^2.
\end{equation}

\begin{equation}\label{vequalg}
\m{M}{\m{v}}^t=\m{M}{\m{g}}^t \quad \Longleftrightarrow \quad \bar{\m{v}}^t=\bar{\m{g}}^t,
\end{equation}

By the above formula \eqref{tracking} and Lemma~\ref{property W}, it follows from induction that
\begin{equation}\label{vequalg}
\m{M}{\m{v}}^t=\m{M}{\m{g}}^t \quad \Longleftrightarrow \quad \bar{\m{v}}^t=\bar{\m{g}}^t,
\end{equation} 
which shows the average of $\m{v}_i^t$ over $i$ is the same as the local gradient average.

\begin{lemma}\label{lem2.5}
	Suppose Assumption \ref{as0} holds. Consider the NDCG algorithm with  $ \alpha \in(0,\frac{1}{4L}]$. Then, for all $t \geq 0$ and any $i$, we have
	\begin{align}
		&\left(2-\xi^t\right)\left\|\tilde{\m{v}}_i^t\right\|^2  \leq -(\tilde{\m{v}}_i^t)\tr\tilde{\m{d}}_i^t \leq \xi^t\left\|\tilde{\m{v}}_i^t\right\|^2, \label{descent1}\\
		&\left(2-\xi^t\right)\left\|\tilde{\m{v}}_i^t\right\| \leq\left\|\tilde{\m{d}}_i^t\right\| \leq \xi^t\left\|\tilde{\m{v}}_i^t\right\|\label{descent2},
	\end{align}
	where $\xi^t$ is the sequence defined in \eqref{def-xi}.
\end{lemma}

\begin{proof}
	Since $\tilde{\m{d}}_i^0=-\tilde{\m{v}}_i^0$ and $\xi^0=1$, \eqref{descent1} and \eqref{descent2} clearly hold for $t=0$. 
Assume that \eqref{descent1} and \eqref{descent2} hold for some $t$. Then by the Cauchy-Schwartz inequality,  $\m{x}_i^{t+1}=\m{x}_i^{t}+\alpha \tilde{\m{d}}_i^{t}$ and \eqref{3.1}, 
we have
	\begin{align}\label{lem2.5_eq1}
		\|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|=&\|\beta_i^{t+1} \tilde{\m{d}}_i^{t}\|
		\leq \frac{\|{\m{g}}^{t+1}_i-{\m{g}}^{t}_i\| \|\tilde{\m{v}}^{t+1}_i\|}{\|\tilde{\m{v}}^{t}_i\|^2}\|\tilde{\m{d}}_i^{t}\| \\
		\leq &\frac{L\alpha \|\tilde{\m{d}}_i^{t}\|^2}{\|\tilde{\m{v}}^{t}_i\|^2}\|\tilde{\m{v}}^{t+1}_i\|
		\leq L\alpha (\xi^t)^2\|\tilde{\m{v}}^{t+1}_i\|.\notag
	\end{align}
	By the triangular inequality and the above relation, we obtain
	\begin{align*}
		\|\tilde{\m{d}}_i^{t+1}\|\leq \|\tilde{\m{v}}_i^{t+1}\|+\|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|\leq \left(1+L\alpha (\xi^t)^2\right)\|\tilde{\m{v}}^{t+1}_i\|
	\end{align*}
	and
	\begin{align*}
		\|\tilde{\m{d}}_i^{t+1}\|\geq \|\tilde{\m{v}}_i^{t+1}\|-\|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|
		\geq \left(1-L\alpha (\xi^t)^2\right)\|\tilde{\m{v}}^{t+1}_i\|.
	\end{align*}
	Then, it follows from the recursion  \eqref{def-xi} of $\xi^t$ and the choice of $\alpha$ that \eqref{descent2} holds for $t+1$. 
       By \eqref{lem2.5_eq1} and the Cauchy-Schwartz inequality, we have that
	\begin{align*}
		\vert (\tilde{\m{v}}_i^{t+1})\tr\tilde{\m{d}}_i^{t+1}+\|\tilde{\m{v}}_i^{t+1}\|^2 \vert 
		\leq \|\tilde{\m{v}}_i^{t+1}\| \|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|
		\leq  L\alpha (\xi^t)^2\|\tilde{\m{v}}^{t+1}_i\|^2.
	\end{align*}
	Similarly, by the recursion  \eqref{def-xi} of $\xi^t$ and the choice of $\alpha$, \eqref{descent1} holds for $t+1$.
\end{proof}

By the triangular inequality and the above relation, we obtain
\begin{align*}
	\|\tilde{\m{d}}_i^{t+1}\|\leq \|\tilde{\m{v}}_i^{t+1}\|+\|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|\leq \left(1+L\alpha (\xi^t)^2\right)\|\tilde{\m{v}}^{t+1}_i\|
\end{align*}
and
\begin{align*}
	\|\tilde{\m{d}}_i^{t+1}\|\geq \|\tilde{\m{v}}_i^{t+1}\|-\|\tilde{\m{d}}_i^{t+1}+\tilde{\m{v}}_i^{t+1}\|
	\geq \left(1-L\alpha (\xi^t)^2\right)\|\tilde{\m{v}}^{t+1}_i\|.
\end{align*}
Then, it follows from the recursion  \eqref{def-xi} of $\xi^t$ and the choice of $\alpha$ that \eqref{descent2} holds for $t+1$.

\begin{lemma}
	Suppose Assumption~\ref{as0} holds. If $ \alpha \in(0,\frac{2\sqrt{5}-4}{5L}]$, then for all $t \geq 0$ we have
	\begin{align}
		F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}}\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}-\left(\frac{\alpha(5-2\sqrt{5})}{4 n}-\frac{5L\alpha^2}{8n}\right)\|\tilde{\m{v}}^t\|^2 \notag \\
&+\frac{16L^2\alpha}{n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{16\alpha}{n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2. \label{term1}
	\end{align} 
\end{lemma}

\begin{proof}
	By Assumption \ref{as0},  $F$ is Lipschitz continuously differentiable with Lipschitz constant $L$, which gives
	\begin{align*}
		F(\bar{\m{x}}^{t+1})\leq F(\bar{\m{x}}^t)+\Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle+\frac{L}{2}\|\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\|^{2}.
	\end{align*}
	Since $\rho(\m{I}-\m{W})<2$, we  have
	\begin{align*}
		\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \leq \frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}+\frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle + \frac{1}{2\alpha n}\|\m{x}^{t+1}-\m{x}^t\|^2.
	\end{align*}
In addition, we have
\begin{align*}
	&\frac{L}{2}\|\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\|^{2}=\frac{L}{2n}\|\m{1}\otimes\bar{\m{x}}^{t+1}-\m{1}\otimes\bar{\m{x}}^{t}\|^{2}=\frac{L}{2n}\|\m{M}{\m{x}}^{t+1}-\m{M}{\m{x}}^{t}\|^{2}\leq\frac{L}{2n}\|{\m{x}}^{t+1}-{\m{x}}^{t}\|^{2}.
\end{align*}
	Adding the above three inequalities together and using Lemma~\ref{lem2.5} yields 
	\begin{eqnarray}\label{add}
	   & & F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \\
  &\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}+\left(\frac{L\alpha^2c^2}{2n}+\frac{\alpha c^2}{2 n}\right) \|\tilde{\m{v}}^t\|^2 + \mbox{RemainTerm} \notag 
	\end{eqnarray}
	where 
	\begin{align}
		&\mbox{RemainTerm} = \Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle + \frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle \notag\\
		=&\frac{1}{n} \sum_{i=1}^n \Big\langle\nabla F(\bar{\m{x}}^t),{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle+\frac{1}{n} \sum_{i=1}^n \Big\langle \frac{1}{\alpha} (\m{x}_i^{t}-\sum_{j \in \mathcal{N}_i} \tilde{W}_{i j} \m{x}_j^{t}), \m{x}_i^{t+1}-\m{x}_i^t\Big\rangle \notag\\
		=&\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\tilde{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (A)}}
		+\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\nabla F(\bar{\m{x}}^t)-\overline{\nabla} f({\m{x}}^t),{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (B)}}\notag\\
		&+\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\overline{\nabla} f({\m{x}}^t)-{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (C)}}. \label{terms}
	\end{align}
	For term (A), by Lemma~\ref{lem2.5} and $\m{x}_i^{t+1}=\m{x}_i^{t}+\alpha \tilde{\m{d}}_i^{t}$, we have
	\begin{align}\label{termA}
		\frac{1}{n} \sum_{i=1}^n \Big\langle\tilde{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle \leq -\frac{\alpha(2-c)}{ n} \|\tilde{\m{v}}^t\|^2.
	\end{align}
	For term (B), by Young's inequality with constant $b >0$ and  $\m{1}\otimes\bar{\m{x}}^t=\m{M}{\m{x}}^t$, we have 
	\begin{eqnarray}\label{termB}
	  &&	\frac{1}{n} \sum_{i=1}^n \Big\langle\nabla F(\bar{\m{x}}^t)-\overline{\nabla} f({\m{x}}^t),{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle \\
  &\leq& \frac{b}{2}\|\nabla F(\bar{\m{x}}^t)-\overline{\nabla} f({\m{x}}^t)\|^2+\frac{1}{2nb}\|{\m{x}}^{t+1}-{\m{x}}^{t}\|^2 \notag\\
		&\leq & \frac{L^2b}{2n}\|\m{1}\otimes\bar{\m{x}}^t-\m{x}^t \|^2+\frac{2\alpha^2}{nb}\|\tilde{\m{v}}^t\|^2
	   =\frac{L^2b}{2n}\|\m{M}\m{x}^t-\m{x}^t \|^2+\frac{2\alpha^2}{nb}\|\tilde{\m{v}}^t\|^2,\notag
	\end{eqnarray}
where the last inequality uses Lemma~\ref{important}, Lemma~\ref{lem2.5},  $L$-Lipschitz continuity of $\nabla F$.
	For term (C), by Young's inequality with constant $d>0$, we have
	\begin{align}\label{termC}
		\frac{1}{n} \sum_{i=1}^n \Big\langle\overline{\nabla} f({\m{x}}^t)-{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle \leq &\frac{d}{2n}\|\m{1}\otimes\overline{\nabla} f({\m{x}}^t)-{\m{v}}^t\|^2+\frac{1}{2nd}\|{\m{x}}^{t+1}-{\m{x}}^{t}\|^2 \notag \\
		\leq & \frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2+\frac{2\alpha^2}{nd}\|\tilde{\m{v}}^t\|^2,
	\end{align}
where the last inequality is due to Lemma~\ref{lem2.5} and the relation $\m{1}\otimes\overline{\nabla} f({\m{x}}^t)=\m{M}{\m{v}}^t$ by \eqref{vequalg}.
	Substituting \eqref{termA}, \eqref{termB}, and \eqref{termC} into \eqref{terms}, we obtain
	\begin{align*}
		&\Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle+\frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle\\
		\leq &-\left(\frac{\alpha(2-c)}{ n}-\frac{2\alpha^2}{n}\left(\frac{1}{b}+\frac{1}{d}\right)\right)\|\tilde{\m{v}}^t\|^2
		+\frac{L^2b}{2n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2.
	\end{align*}
	By substituting the above inequality into \eqref{add}, it holds that
	\begin{eqnarray*}
	&& F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \\ 
      &\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}
	-\left(\frac{\alpha(4-2c-c^2)}{ 2n}-\frac{2\alpha^2}{n}\left(\frac{1}{b}+\frac{1}{d}\right)-\frac{L\alpha^2c^2}{2n}\right)\|\tilde{\m{v}}^t\|^2\\
	&&+\frac{L^2b}{2n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2.
\end{eqnarray*} 
Since $0<\alpha \leq \frac{2\sqrt{5}-4}{5L}$, we have from the definition of constant $c$ in \eqref{const-c} that 
\begin{equation}\label{new-bd-c}
1<c\leq \sqrt{5}/2, 
\end{equation}
 which implies $\frac{11}{4}-\sqrt{5}\leq 4-2c-c^2 \leq 1$. Then, setting $b=d=32\alpha$ yields \eqref{term1}.
%	\begin{align*}
%		F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}}\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}-\left(\frac{\alpha(5-2\sqrt{5})}{4 n}-\frac{5L\alpha^2}{8n}\right)\| \tilde{\m{v}}^t\|^2\\
%		&+\frac{16L^2\alpha}{n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{16\alpha}{n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2.
%	\end{align*} 
\end{proof}

By Assumption \ref{as0},  $F$ is Lipschitz continuously differentiable with Lipschitz constant $L$, which gives
\begin{align*}
	F(\bar{\m{x}}^{t+1})\leq F(\bar{\m{x}}^t)+\Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle+\frac{L}{2}\|\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\|^{2}.
\end{align*}

Since $\rho(\m{I}-\m{W})<2$, we  have
\begin{align*}
	\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \leq \frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}+\frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle + \frac{1}{2\alpha n}\|\m{x}^{t+1}-\m{x}^t\|^2.
\end{align*}

In addition, we have
\begin{align*}
	&\frac{L}{2}\|\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\|^{2}=\frac{L}{2n}\|\m{1}\otimes\bar{\m{x}}^{t+1}-\m{1}\otimes\bar{\m{x}}^{t}\|^{2}=\frac{L}{2n}\|\m{M}{\m{x}}^{t+1}-\m{M}{\m{x}}^{t}\|^{2}\leq\frac{L}{2n}\|{\m{x}}^{t+1}-{\m{x}}^{t}\|^{2}.
\end{align*}

	Adding the above three inequalities together and using Lemma~\ref{lem2.5} yields 
	\begin{eqnarray}\label{add}
	   & & F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \\
  &\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}+\left(\frac{L\alpha^2c^2}{2n}+\frac{\alpha c^2}{2 n}\right) \|\tilde{\m{v}}^t\|^2 + \mbox{RemainTerm} \notag 
	\end{eqnarray}

where 
\begin{align}
	&\mbox{RemainTerm} = \Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle + \frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle \notag\\
	=&\frac{1}{n} \sum_{i=1}^n \Big\langle\nabla F(\bar{\m{x}}^t),{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle+\frac{1}{n} \sum_{i=1}^n \Big\langle \frac{1}{\alpha} (\m{x}_i^{t}-\sum_{j \in \mathcal{N}_i} \tilde{W}_{i j} \m{x}_j^{t}), \m{x}_i^{t+1}-\m{x}_i^t\Big\rangle \notag\\
	=&\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\tilde{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (A)}}
	+\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\nabla F(\bar{\m{x}}^t)-\overline{\nabla} f({\m{x}}^t),{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (B)}}\notag\\
	&+\underbrace{\frac{1}{n} \sum_{i=1}^n \Big\langle\overline{\nabla} f({\m{x}}^t)-{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle}_{\text {term (C)}}. \label{terms}
\end{align}

For term (A), by Lemma~\ref{lem2.5} and $\m{x}_i^{t+1}=\m{x}_i^{t}+\alpha \tilde{\m{d}}_i^{t}$, we have
\begin{align}\label{termA}
	\frac{1}{n} \sum_{i=1}^n \Big\langle\tilde{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle \leq -\frac{\alpha(2-c)}{ n} \|\tilde{\m{v}}^t\|^2.
\end{align}

	For term (C), by Young's inequality with constant $d>0$, we have
	\begin{align}\label{termC}
		\frac{1}{n} \sum_{i=1}^n \Big\langle\overline{\nabla} f({\m{x}}^t)-{\m{v}}_i^t,{\m{x}}_i^{t+1}-{\m{x}}_i^{t}\Big\rangle \leq &\frac{d}{2n}\|\m{1}\otimes\overline{\nabla} f({\m{x}}^t)-{\m{v}}^t\|^2+\frac{1}{2nd}\|{\m{x}}^{t+1}-{\m{x}}^{t}\|^2 \notag \\
		\leq & \frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2+\frac{2\alpha^2}{nd}\|\tilde{\m{v}}^t\|^2,
	\end{align}
where the last inequality is due to Lemma~\ref{lem2.5} and the relation $\m{1}\otimes\overline{\nabla} f({\m{x}}^t)=\m{M}{\m{v}}^t$ by \eqref{vequalg}.

Substituting \eqref{termA}, \eqref{termB}, and \eqref{termC} into \eqref{terms}, we obtain
\begin{align*}
	&\Big\langle\nabla F(\bar{\m{x}}^t),\bar{\m{x}}^{t+1}-\bar{\m{x}}^{t}\Big\rangle+\frac{1}{n} \Big\langle \frac{1}{\alpha} (\m{I}-\m{W})\m{x}^t, \m{x}^{t+1}-\m{x}^t\Big\rangle\\
	\leq &-\left(\frac{\alpha(2-c)}{ n}-\frac{2\alpha^2}{n}\left(\frac{1}{b}+\frac{1}{d}\right)\right)\|\tilde{\m{v}}^t\|^2
	+\frac{L^2b}{2n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2.
\end{align*}

	By substituting the above inequality into \eqref{add}, it holds that
	\begin{eqnarray*}
	&& F(\bar{\m{x}}^{t+1})+\frac{1}{2\alpha n} \|\m{x}^{t+1}\|^2_{\m{I}-\m{W}} \\ 
      &\leq& F(\bar{\m{x}}^t)+\frac{1}{2\alpha n} \|\m{x}^{t}\|^2_{\m{I}-\m{W}}
	-\left(\frac{\alpha(4-2c-c^2)}{ 2n}-\frac{2\alpha^2}{n}\left(\frac{1}{b}+\frac{1}{d}\right)-\frac{L\alpha^2c^2}{2n}\right)\|\tilde{\m{v}}^t\|^2\\
	&&+\frac{L^2b}{2n}\|\m{x}^t-\m{M}\m{x}^t\|^2+\frac{d}{2n}\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2.
\end{eqnarray*}

Since $0<\alpha \leq \frac{2\sqrt{5}-4}{5L}$, we have from the definition of constant $c$ in \eqref{const-c} that 
\begin{equation}\label{new-bd-c}
1<c\leq \sqrt{5}/2, 
\end{equation}
 which implies $\frac{11}{4}-\sqrt{5}\leq 4-2c-c^2 \leq 1$. Then, setting $b=d=32\alpha$ yields \eqref{term1}.

\begin{theorem}\label{nonconvex_convergence}
	Suppose Assumption \ref{as0} holds. If
	\begin{align}\label{alpha}
	0 <	\alpha < \min \left\{\frac{(1-{\sigma}^2)n}{32L^2},\frac{2(5-2\sqrt{5})(1-{\sigma}^2)}{4n(5\sigma^2L^2+18-8\sqrt{5})+5L},\frac{2\sqrt{5}-4}{5L}\right\},
	\end{align}
	then we have  
	\begin{equation}\label{cg-converge-rate}
	 \min_{0 \le t \le T} \left\{ \|\tilde{\m{v}}^t\|^2+\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2+\|\m{x}^{t}-\m{M}\m{x}^{t}\|^2 \right\}
		\leq \frac{P(\m{x}^{0};\m{v}^{0})-P(\m{x}^{T};\m{v}^{T})}{\gamma \min\{\alpha,1\}T},
	\end{equation}
	where $P$ is the potential function defined in \eqref{Potential-P} and
	$\gamma >0$ is a constant depending only on $n$, $L$, and $\sigma$.
\end{theorem}

Suppose Assumption \ref{as0} holds. If
\begin{align}\label{alpha}
0 <	\alpha < \min \left\{\frac{(1-{\sigma}^2)n}{32L^2},\frac{2(5-2\sqrt{5})(1-{\sigma}^2)}{4n(5\sigma^2L^2+18-8\sqrt{5})+5L},\frac{2\sqrt{5}-4}{5L}\right\},
\end{align}

Then, by the choice of $\alpha$ in \eqref{alpha}, we can derive from \eqref{P_descent}
and direct calculations	that there exist a constant $\gamma >0$, depending only on 
$n$, $L$, $\sigma$, such that
\begin{equation*}
	P(\m{x}^{t+1},\m{v}^{t+1}) \leq P(\m{x}^{t},\m{v}^{t}) - \gamma \left( 
	\alpha \|\tilde{\m{v}}^t\|^2 +\|{\m{v}}^t-\m{M}{\m{v}}^t\|^2+\|\m{x}^{t}-\m{M}\m{x}^{t}\|^2 \right). 
\end{equation*}
